// The adaptor has no generic request helper: it only exposes send().
// Closest option: call a method on the mailgun.js client it sets up on
// state.client. For example, list the account's mailing lists:
fn(async state => {
  const lists = await state.client.lists.list();
  return { ...state, data: lists };
});
